-- Add cosmetic player-builder fields; existing family/player RLS remains authoritative.
alter table public.player_space_profiles add column builder_look jsonb, add column builder_on_card boolean not null default false;
grant update(builder_look,builder_on_card) on public.player_space_profiles to authenticated;
create or replace function star_private.validate_builder_look() returns trigger language plpgsql set search_path='' as $$
declare v jsonb:=new.builder_look;
begin
 perform pg_advisory_xact_lock(hashtextextended('builder:'||new.player_id::text,0));
 if v is not null then
  if jsonb_typeof(v)<>'object' or (select count(*) from jsonb_object_keys(v))<>11 then raise exception 'Choose an available player look' using errcode='23514';end if;
  if jsonb_typeof(v->'skin') is distinct from 'string' or not((v->>'skin')=any(array['fair','light','medium','brown','deep'])) then raise exception 'Choose an available skin' using errcode='23514';end if;
  if jsonb_typeof(v->'hair') is distinct from 'string' or not((v->>'hair')=any(array['blonde','brown','black','ginger','silver'])) then raise exception 'Choose an available hair' using errcode='23514';end if;
  if jsonb_typeof(v->'hairstyle') is distinct from 'string' or not((v->>'hairstyle')=any(array['ponytail','curls','coils','braids'])) then raise exception 'Choose an available hairstyle' using errcode='23514';end if;
  if jsonb_typeof(v->'face') is distinct from 'string' or not((v->>'face')=any(array['oval','round','freckles'])) then raise exception 'Choose an available face' using errcode='23514';end if;
  if jsonb_typeof(v->'eyes') is distinct from 'string' or not((v->>'eyes')=any(array['brown','blue','green','grey'])) then raise exception 'Choose an available eyes' using errcode='23514';end if;
  if jsonb_typeof(v->'build') is distinct from 'string' or not((v->>'build')=any(array['slim','standard','strong'])) then raise exception 'Choose an available build' using errcode='23514';end if;
  if jsonb_typeof(v->'top') is distinct from 'string' or not((v->>'top')=any(array['base','star','arsenal','chelsea','navy-tee','white-tee','hoodie','gold-hoodie'])) then raise exception 'Choose an available top' using errcode='23514';end if;
  if jsonb_typeof(v->'bottoms') is distinct from 'string' or not((v->>'bottoms')=any(array['base','shorts','arsenal','chelsea','leggings','trackies'])) then raise exception 'Choose an available bottoms' using errcode='23514';end if;
  if jsonb_typeof(v->'socks') is distinct from 'string' or not((v->>'socks')=any(array['none','white','navy','black','red'])) then raise exception 'Choose an available socks' using errcode='23514';end if;
  if jsonb_typeof(v->'accessory') is distinct from 'string' or not((v->>'accessory')=any(array['none','glasses','headband','gold-headband'])) then raise exception 'Choose an available accessory' using errcode='23514';end if;
  if jsonb_typeof(v->'boots') is distinct from 'string' or not((v->>'boots')=any(array['none','starter','ida-rise','furon-pink','tekela-white','morelia-ruby','superfly-pink','absolute-2006','total90-2004','stadio-1990','etrusco-1990','tiempo','copa','mercurial','predator','future','ultra','phantom','f50'])) then raise exception 'Choose boots from your locker' using errcode='23514';end if;
  if v->>'boots' not in ('none','starter') and not exists(select 1 from public.player_cosmetic_unlocks u where u.player_id=new.player_id and u.cosmetic='boot-'||(v->>'boots')) then raise exception 'Unlock these boots first' using errcode='23514';end if;
  if (v->>'top'='gold-hoodie' or v->>'accessory'='gold-hoodie') and not exists(select 1 from public.player_cosmetic_unlocks u where u.player_id=new.player_id and u.cosmetic='avatar-captain') then raise exception 'Earn your first coach badge' using errcode='23514';end if;
  if (v->>'top'='gold-headband' or v->>'accessory'='gold-headband') and not exists(select 1 from public.player_cosmetic_unlocks u where u.player_id=new.player_id and u.cosmetic='decoration-laurel') then raise exception 'Earn three coach badges' using errcode='23514';end if;
 end if;
 if (new.builder_on_card or exists(select 1 from public.player_squads s where s.player_id=new.player_id and 'my-player'=any(s.footballers))) and (v is null or v->>'top'='base' or v->>'bottoms'='base') then raise exception 'Choose a top and bottoms while your player is on your card or in your squad' using errcode='23514';end if;
 return new;
end $$;
revoke all on function star_private.validate_builder_look() from public,anon,authenticated;
create trigger validate_builder_look before insert or update of builder_look,builder_on_card on public.player_space_profiles for each row execute function star_private.validate_builder_look();
create or replace function star_private.validate_player_squad() returns trigger language plpgsql set search_path='' as $$
declare expected integer;selected text;keepers text[]:=array['brosnan','kop','roebuck','hampton','yamashita','tullis-joyce','sophie-baggaley','chiamaka-nnadozie','sophie-whitehouse','shae-yanez','khiara-keating','mary-earps','constance-picaud','daphne-van-domselaar','pauline-peyraud-magnin','fran-bentley','kirstie-levell','anna-king','lysianne-proulx','olivia-clark','anna-tamminen','katie-cox','sian-rogers','grace-moloney','frances-stenson','safia-middleton-patel','alex-brooks'];roster text[]:=array['my-player','hemp','blindkilde','kelly','caldentey','walsh','carpenter','fisk','brosnan','koga','stanway','kop','roebuck','asllani','godfrey','tierney','goodwin','hampton','yamashita','tullis-joyce','williamson','fox','bronze','greenwood','le-tissier','little','cuthbert','hasegawa','toone','kirby','kendall','russo','james','shaw','terland','seike','daly','anna-patten','lynn-wilms','missy-bo-kearns','sophie-baggaley','millie-turner','neve-herron','lisa-naalsund','lily-crosthwaite','veatriki-sarri','chiamaka-nnadozie','marisa-olislagers','maisie-symonds','madison-haley','sophie-whitehouse','ellie-mason','kiera-skeels','jodie-hutton','lucy-fitzgerald','gillian-kenney','shae-yanez','allyson-swaby','aimee-everett','annabel-blanchard','ashleigh-weerden','bethany-england','ruby-mace','mayumi-pacheco','clare-wheeler','yuka-momiki','ornella-vignola','khiara-keating','jenna-clark','fuka-nagano','ceri-holland','beata-olsson','mary-earps','maria-leon','alexia-putellas','kadidiatou-diani','anna-sandberg','jessica-park','amanda-nilden','olivia-holdt','jessica-naz','cathinka-tandberg','constance-picaud','estelle-cascarino','ffion-morgan','katie-zelem','riko-ueki','ebony-salmon','asmita-ale','daphne-van-domselaar','sjoeke-nusken','vivianne-miedema','kirsty-hanson','caitlin-hayes','hikaru-kitagawa','mia-enderby','grace-geyoro','rebeca-bernal','noelle-maritz','lotte-wubben-moy','drew-spence','seraina-piubel','danielle-van-de-donk','shannon-cooke','pauline-peyraud-magnin','elisha-n-dow','aoba-fujino','aggie-beever-jones','aurora-galli','naomi-girma','hinata-miyazawa','olivia-smith','victoria-pelova','maelys-mpome','megan-finnigan','simone-magill','kirsty-howat','rebecca-knaak','nikita-parris','fran-bentley','brooke-aspin','ella-powell','marine-dafeur','lotta-lindstrom','kirstie-levell','maddi-wilde','jamie-finn','rachel-williams','charlie-wellings','anna-king','emma-brown','beth-hepple','lucy-watson','olivia-fergusson','lysianne-proulx','jorja-fox','jenna-slattery','mary-mcateer','princess-ademiluyi','olivia-clark','olivia-mcloughlin','poppy-pritchard','alisha-lehmann','anna-tamminen','demi-stokes','jordan-nobbs','beth-lumsden','katie-cox','chloe-mustaki','codie-thomas','tove-almqvist','aimee-claypole','sian-rogers','chloe-warrington','tilly-bristow','halle-houssein','ava-baker','grace-moloney','amy-goddard','lilly-mitchell','emma-harries','maria-edwards','frances-stenson','rhiannon-roberts','chloe-paxton','katie-kitching','izzy-atkinson','safia-middleton-patel','eden-skyers','poppy-wilson','madison-perry','alex-brooks','tara-ohanlon','melissa-lawley','chloe-williams','yana-daniels'];
begin
 perform pg_advisory_xact_lock(hashtextextended('builder:'||new.player_id::text,0));
 if tg_op='UPDATE' and new.player_id<>old.player_id then raise exception 'A squad stays with its player' using errcode='23514';end if;
 expected:=case when new.formation in ('diamond','box') then 5 when new.formation in ('4-3-3','4-4-2','4-2-3-1') then 11 else null end;
 if expected is null then raise exception 'Choose a formation' using errcode='23514';end if;
 if new.footballers is null or cardinality(new.footballers)<>expected or (select count(distinct p) from unnest(new.footballers) p)<>expected then raise exception 'Choose % different players',expected using errcode='23514';end if;
 if 'my-player'=any(new.footballers) and not exists(select 1 from public.player_space_profiles p where p.player_id=new.player_id and p.builder_look is not null and p.builder_look->>'top'<>'base' and p.builder_look->>'bottoms'<>'base') then raise exception 'Save your dressed player first' using errcode='23514';end if;
 foreach selected in array new.footballers loop
  if selected is null or not(selected=any(roster)) then raise exception 'Choose a player from the roster' using errcode='23514';end if;
 end loop;
 if not(new.footballers[1]=any(keepers)) or exists(select 1 from unnest(new.footballers[2:expected]) p where p=any(keepers)) then raise exception 'Choose one goalkeeper and % outfield players',expected-1 using errcode='23514';end if;
 if not(new.captain=any(new.footballers)) then raise exception 'Choose a captain from your squad' using errcode='23514';end if;
 new.name:=btrim(new.name);new.updated_at:=now();return new;
end $$;
notify pgrst,'reload schema';
